const rescheduleDepartureStops = `-- name: RescheduleDepartureStops :exec
UPDATE departure_stops SET scheduled_at = scheduled_at + ($1::timestamptz - $2::timestamptz)
WHERE departure_id = $3
`

type RescheduleDepartureStopsParams struct {
	NewDepartureAt time.Time
	OldDepartureAt time.Time
	DepartureID    uuid.UUID
}

// Nouvel horaire : tous les arrêts sont décalés d'autant.
func (q *Queries) RescheduleDepartureStops(ctx context.Context, arg RescheduleDepartureStopsParams) error {
	_, err := q.db.Exec(ctx, rescheduleDepartureStops, arg.NewDepartureAt, arg.OldDepartureAt, arg.DepartureID)
	return err
}

const setRouteItinerary = `-- name: SetRouteItinerary :one
UPDATE routes SET origin_agency_id = $1, destination_agency_id = $2,
                  duration_minutes = $3, pricing_mode = $4
WHERE id = $5 AND company_id = $6
RETURNING id, company_id, origin_agency_id, destination_agency_id, name, base_price, duration_minutes, distance_km, included_baggage_kg, is_active, created_at, updated_at, pricing_mode
`

type SetRouteItineraryParams struct {
	OriginAgencyID      uuid.UUID
	DestinationAgencyID *uuid.UUID
	DurationMinutes     int32
	PricingMode         string
	ID                  uuid.UUID
	CompanyID           uuid.UUID
}

// Extrémités et durée recalculées à partir des arrêts (compatibilité des écrans existants).
func (q *Queries) SetRouteItinerary(ctx context.Context, arg SetRouteItineraryParams) (Route, error) {
	row := q.db.QueryRow(ctx, setRouteItinerary,
		arg.OriginAgencyID,
		arg.DestinationAgencyID,
		arg.DurationMinutes,
		arg.PricingMode,
		arg.ID,
		arg.CompanyID,
	)
	var i Route
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.OriginAgencyID,
		&i.DestinationAgencyID,
		&i.Name,
		&i.BasePrice,
		&i.DurationMinutes,
		&i.DistanceKm,
		&i.IncludedBaggageKg,
		&i.IsActive,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.PricingMode,
	)
	return i, err
}

const staffBusyOnDeparture = `-- name: StaffBusyOnDeparture :one
SELECT d.id, d.departure_at, r.name AS route_name
FROM departures d
JOIN routes r ON r.id = d.route_id
WHERE d.company_id = $1
  AND d.status NOT IN ('cancelled', 'arrived')
  AND ($2::uuid IS NULL OR d.id <> $2::uuid)
  AND d.departure_at < $3 AND d.arrival_eta > $4
  AND (d.agent_id = $5 OR d.driver_id = $5
       OR EXISTS (SELECT 1 FROM departure_crew c WHERE c.departure_id = d.id AND c.staff_id = $5))
LIMIT 1
`

type StaffBusyOnDepartureParams struct {
	CompanyID uuid.UUID
	ExcludeID *uuid.UUID
	ToTs      time.Time
	FromTs    time.Time
	StaffID   *uuid.UUID
}

type StaffBusyOnDepartureRow struct {
	ID          uuid.UUID
	DepartureAt time.Time
	RouteName   string
}

// Membre d'équipage déjà affecté à un autre départ qui chevauche ce créneau.
func (q *Queries) StaffBusyOnDeparture(ctx context.Context, arg StaffBusyOnDepartureParams) (StaffBusyOnDepartureRow, error) {
	row := q.db.QueryRow(ctx, staffBusyOnDeparture,
		arg.CompanyID,
		arg.ExcludeID,
		arg.ToTs,
		arg.FromTs,
		arg.StaffID,
	)
	var i StaffBusyOnDepartureRow
	err := row.Scan(&i.ID, &i.DepartureAt, &i.RouteName)
	return i, err
}

const stopDeparted = `-- name: StopDeparted :one
SELECT EXISTS (SELECT 1 FROM departure_stop_visits
               WHERE departure_id = $1 AND seq = $2 AND departed_at IS NOT NULL)::bool
`

type StopDepartedParams struct {
	DepartureID uuid.UUID
	Seq         *int32
}

func (q *Queries) StopDeparted(ctx context.Context, arg StopDepartedParams) (bool, error) {
	row := q.db.QueryRow(ctx, stopDeparted, arg.DepartureID, arg.Seq)
	var column_1 bool
	err := row.Scan(&column_1)
	return column_1, err
}

